#!/usr/bin/env node
import { spawnSync } from "node:child_process"
import { createHash } from "node:crypto"
import { mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises"
import { builtinModules } from "node:module"
import { dirname, join, relative, resolve } from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"

// Keep this list byte-for-byte aligned with senpi loader.ts lines 145-165.
export const SENPI_LOADER_ALIASES = [
  "@earendil-works/pi-coding-agent",
  "@earendil-works/pi-agent-core",
  "@earendil-works/pi-tui",
  "@earendil-works/pi-ai",
  "@earendil-works/pi-ai/compat",
  "@earendil-works/pi-ai/oauth",
  "@code-yeongyu/senpi",
  "@mariozechner/pi-coding-agent",
  "@mariozechner/pi-agent-core",
  "@mariozechner/pi-tui",
  "@mariozechner/pi-ai",
  "@mariozechner/pi-ai/compat",
  "@mariozechner/pi-ai/oauth",
  "typebox",
  "typebox/compile",
  "typebox/value",
  "@sinclair/typebox",
  "@sinclair/typebox/compile",
  "@sinclair/typebox/value",
]

const scriptDir = dirname(fileURLToPath(import.meta.url))
const pluginRoot = dirname(scriptDir)
const packageRoot = dirname(pluginRoot)
const repoRoot = join(packageRoot, "..", "..")
const entryPath = join(packageRoot, "src", "extension", "index.ts")
const outputPath = join(pluginRoot, "extensions", "omo.js")
const memberEntryPath = join(repoRoot, "packages", "senpi-task", "src", "team", "member-extension", "index.ts")
const memberOutputPath = join(pluginRoot, "extensions", "omo-member.js")
const reflectionPersonaSource = join(repoRoot, "packages", "memory-core", "src", "reflection", "assets", "reflection-persona.md")
const builtinModuleNames = builtinModules
  .filter((moduleName) => !moduleName.startsWith("_"))
  .sort()
const externalSpecifiers = [
  ...SENPI_LOADER_ALIASES,
  ...builtinModuleNames,
  ...builtinModuleNames.map((moduleName) => `node:${moduleName}`),
]
const BUILD_MARKER_PREFIX = "// omo-senpi-build:"
const BUILD_SETTINGS = JSON.stringify({
  target: "node",
  format: "esm",
  minify: true,
  loaderAliases: SENPI_LOADER_ALIASES,
})

export async function buildExtension(options = {}) {
  const output = options.outputPath ?? outputPath
  const memberOutput = options.memberOutputPath ?? (options.outputPath === undefined
    ? memberOutputPath
    : join(dirname(output), "omo-member.js"))
  const mainInputs = await buildEntry(entryPath, output)
  const memberInputs = await buildEntry(memberEntryPath, memberOutput)
  // Bundling inlines assets.ts but its markdown is read from disk at runtime next to the bundle,
  // so the persona must be staged into the extension output directory the loader executes from.
  await writeFile(join(dirname(output), "reflection-persona.md"), await readFile(reflectionPersonaSource, "utf8"))
  return { mainInputs, memberInputs }
}

async function buildEntry(entry, output) {
  await mkdir(dirname(output), { recursive: true })
  const metafile = `${output}.meta.json`
  try {
    run("bun", [
      "build", entry, "--target", "node", "--format", "esm", "--outfile", output,
      "--minify", `--metafile=${metafile}`,
      ...externalSpecifiers.flatMap((specifier) => ["--external", specifier]),
    ])
    await normalizeBuiltinImports(output)
    return await attachBuildMarker(output, entry, metafile)
  } finally {
    await rm(metafile, { force: true })
  }
}

export async function checkExtensionCurrent(options = {}) {
  const output = options.outputPath ?? outputPath
  const memberOutput = options.memberOutputPath ?? (options.outputPath === undefined
    ? memberOutputPath
    : join(dirname(output), "omo-member.js"))
  const currentMain = await readBuiltEntry(output)
  if (currentMain === undefined) return { ok: false, reason: "missing-output", output }
  const currentMember = await readBuiltEntry(memberOutput)
  if (currentMember === undefined) return { ok: false, reason: "missing-output", output: memberOutput }

  const tempRoot = await mkdtemp(join(repoRoot, ".build-check-"))
  const expectedOutput = join(tempRoot, "omo.js")
  const expectedMemberOutput = join(tempRoot, "omo-member.js")
  try {
    await buildExtension({ outputPath: expectedOutput, memberOutputPath: expectedMemberOutput })
    if (!artifactsMatch(currentMain, await readFile(expectedOutput, "utf8"))) {
      return { ok: false, reason: "stale-output", output }
    }
    if (!artifactsMatch(currentMember, await readFile(expectedMemberOutput, "utf8"))) {
      return { ok: false, reason: "stale-output", output: memberOutput }
    }
    const expectedPersona = await readFile(join(tempRoot, "reflection-persona.md"), "utf8")
    const currentPersona = await readFile(join(dirname(output), "reflection-persona.md"), "utf8").catch(() => undefined)
    if (currentPersona !== expectedPersona) {
      return { ok: false, reason: "stale-output", output: join(dirname(output), "reflection-persona.md") }
    }
    return { ok: true, output, memberOutput }
  } finally {
    await rm(tempRoot, { recursive: true, force: true })
  }
}

function run(command, args) {
  const result = spawnSync(command, args, {
    cwd: repoRoot,
    shell: process.platform === "win32",
    stdio: "inherit",
  })
  if (result.error !== undefined) throw result.error
  if (result.status !== 0) process.exit(result.status ?? 1)
}

async function normalizeBuiltinImports(output) {
  const bundled = await readFile(output, "utf8")
  // Whitespace-tolerant so minified output (`from"path"`, `import"path"`) normalizes too, not just the
  // spaced non-minified shape.
  const normalized = bundled.replace(
    /(from\s*["']|import\s*\(\s*["']|import\s*["'])([^"']+)(["'])/g,
    (match, prefix, specifier, suffix) => {
      if (specifier.startsWith("node:")) return match
      if (!builtinModuleNames.includes(specifier)) return match
      return `${prefix}node:${specifier}${suffix}`
    },
  ).replace(/^[\t ]+$/gm, "")
  if (normalized !== bundled) {
    await writeFile(output, normalized)
  }
}

async function attachBuildMarker(output, entry, metafile) {
  const body = await readFile(output, "utf8")
  const metadata = JSON.parse(await readFile(metafile, "utf8"))
  const sourceDigest = await digestBuildSources(metadata, entry)
  await writeFile(output, `${BUILD_MARKER_PREFIX}${sourceDigest}:${digest(body)}\n${body}`)
  return Object.keys(metadata.inputs ?? {})
}

async function digestBuildSources(metadata, entry) {
  const inputs = metadata !== null && typeof metadata === "object" && metadata.inputs !== null
    && typeof metadata.inputs === "object" ? Object.keys(metadata.inputs).sort() : []
  const hash = createHash("sha256").update(BUILD_SETTINGS).update(toPortableBuildPath(relative(repoRoot, entry)))
  for (const input of inputs) {
    const inputPath = resolve(repoRoot, input)
    hash.update(toPortableBuildPath(relative(repoRoot, inputPath))).update(await readFile(inputPath))
  }
  hash.update(await readFile(fileURLToPath(import.meta.url)))
  return hash.digest("hex")
}

export function toPortableBuildPath(path) {
  return path.replaceAll("\\", "/")
}

function artifactsMatch(currentText, expectedText) {
  const current = parseBuildArtifact(currentText)
  const expected = parseBuildArtifact(expectedText)
  return current !== undefined && expected !== undefined
    && current.sourceDigest === expected.sourceDigest
    && current.bodyDigest === digest(current.body)
}

function parseBuildArtifact(text) {
  const newline = text.indexOf("\n")
  if (newline < 0) return undefined
  const match = /^\/\/ omo-senpi-build:([a-f0-9]{64}):([a-f0-9]{64})$/.exec(text.slice(0, newline))
  if (match === null) return undefined
  return { sourceDigest: match[1], bodyDigest: match[2], body: text.slice(newline + 1) }
}

function digest(value) {
  return createHash("sha256").update(value).digest("hex")
}

function isErrno(error, code) {
  return error instanceof Error && "code" in error && error.code === code
}

async function readBuiltEntry(output) {
  try {
    return await readFile(output, "utf8")
  } catch (error) {
    if (isErrno(error, "ENOENT")) return undefined
    throw error
  }
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  if (process.argv.includes("--check")) {
    run("node", [join(scriptDir, "stage-lsp-daemon-runtime.mjs"), "--check"])
    run("node", [join(scriptDir, "stage-ast-grep-mcp-runtime.mjs"), "--check"])
    run("node", [join(scriptDir, "stage-agent-toolkit.mjs"), "--check"])
    const result = await checkExtensionCurrent()
    if (!result.ok) {
      console.error(`omo-senpi extension build is not current: ${result.reason}`)
      console.error(`output=${result.output}`)
      process.exit(1)
    }
    console.log(`omo-senpi extension build is current: ${result.output}`)
  } else {
    await buildExtension()
    console.log(`Built omo-senpi extensions: ${outputPath}, ${memberOutputPath}`)
  }
}

import { afterEach, describe, expect, test } from "bun:test"
import { appendFile, mkdtemp, readFile, rm, utimes, writeFile } from "node:fs/promises"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"

import { buildExtension, checkExtensionCurrent, toPortableBuildPath } from "./build-extension.mjs"

const scriptDir = dirname(fileURLToPath(import.meta.url))
const repoRoot = join(scriptDir, "..", "..", "..", "..")
const tempRoots = []

afterEach(async () => {
  await Promise.all(tempRoots.splice(0).map((root) => rm(root, { recursive: true, force: true })))
})

async function builtOutputs() {
  const root = await mkdtemp(join(repoRoot, ".build-extension-test-"))
  tempRoots.push(root)
  const outputPath = join(root, "omo.js")
  const memberOutputPath = join(root, "omo-member.js")
  const build = await buildExtension({ outputPath, memberOutputPath })
  return { outputPath, memberOutputPath, ...build }
}

describe("checkExtensionCurrent", () => {
  test("#given platform-specific source paths #when normalized #then build markers use portable separators", () => {
    expect(toPortableBuildPath("packages\\omo-senpi\\src\\extension\\index.ts"))
      .toBe("packages/omo-senpi/src/extension/index.ts")
    expect(toPortableBuildPath("packages/omo-senpi/src/extension/index.ts"))
      .toBe("packages/omo-senpi/src/extension/index.ts")
  })

  test("#given current generated outputs with old mtimes #when checked #then freshness passes", async () => {
    // given
    const outputs = await builtOutputs()
    const old = new Date(0)
    await Promise.all([utimes(outputs.outputPath, old, old), utimes(outputs.memberOutputPath, old, old)])

    // when
    const result = await checkExtensionCurrent(outputs)

    // then
    expect(result).toMatchObject({ ok: true })
  })

  test("#given changed generated bytes with future mtimes #when checked #then freshness fails", async () => {
    // given
    const outputs = await builtOutputs()
    await appendFile(outputs.outputPath, "\nchanged\n")
    const future = new Date("2100-01-01T00:00:00.000Z")
    await utimes(outputs.outputPath, future, future)

    // when
    const result = await checkExtensionCurrent(outputs)

    // then
    expect(result).toMatchObject({ ok: false, reason: "stale-output", output: outputs.outputPath })
  })

  test("#given intact generated bytes with a stale source digest #when checked #then source reproduction fails", async () => {
    // given
    const outputs = await builtOutputs()
    const artifact = await readFile(outputs.outputPath, "utf8")
    const newline = artifact.indexOf("\n")
    const [prefix, , bodyDigest] = artifact.slice(0, newline).split(":")
    await writeFile(outputs.outputPath, `${prefix}:${"0".repeat(64)}:${bodyDigest}\n${artifact.slice(newline + 1)}`)

    // when
    const result = await checkExtensionCurrent(outputs)

    // then
    expect(result).toMatchObject({ ok: false, reason: "stale-output", output: outputs.outputPath })
  })

  test("#given freshly built outputs #when inspected #then normalization removes whitespace-only lines", async () => {
    // given
    const outputs = await builtOutputs()

    // when
    const main = await readFile(outputs.outputPath, "utf8")
    const member = await readFile(outputs.memberOutputPath, "utf8")

    // then
    expect(main).not.toMatch(/^[\t ]+$/m)
    expect(member).not.toMatch(/^[\t ]+$/m)
  })

  test("#given the main extension build #when its metafile inputs are inspected #then senpi-task implementation sources are included", async () => {
    // given / when
    const inputs = (await builtOutputs()).mainInputs

    // then
    expect(inputs.some((input) => input.endsWith("packages/senpi-task/src/runners/in-process/curated-readonly-bash.ts"))).toBe(true)
  })
})

#!/usr/bin/env node
import { spawnSync } from "node:child_process"
import { mkdir } from "node:fs/promises"
import { dirname, join } from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"

const scriptDir = dirname(fileURLToPath(import.meta.url))
const pluginRoot = dirname(scriptDir)
const packageRoot = dirname(pluginRoot)
const repoRoot = join(packageRoot, "..", "..")
const entryPath = join(packageRoot, "src", "install", "cli-local.ts")
const outputPath = join(pluginRoot, "scripts", "install.mjs")

export async function buildInstallCli(options = {}) {
  const output = options.outputPath ?? outputPath
  await mkdir(dirname(output), { recursive: true })
  const result = spawnSync(
    "bun",
    [
      "build",
      entryPath,
      "--target",
      "node",
      "--format",
      "esm",
      "--outfile",
      output,
      "--external",
      "@code-yeongyu/senpi",
      "--external",
      "typebox",
      "--external",
      "typebox/compile",
      "--external",
      "typebox/value",
    ],
    {
      cwd: repoRoot,
      shell: process.platform === "win32",
      stdio: "inherit",
    },
  )
  if (result.error !== undefined) throw result.error
  if (result.status !== 0) process.exit(result.status ?? 1)
  return { output }
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  await buildInstallCli()
  console.log(`Built omo-senpi installer: ${outputPath}`)
}

#!/usr/bin/env node

import { readFileSync, writeFileSync } from "node:fs"
import { dirname, resolve } from "node:path"
import { fileURLToPath } from "node:url"

const scriptDir = dirname(fileURLToPath(import.meta.url))
const packageRoot = resolve(scriptDir, "../..")
const repoRoot = resolve(packageRoot, "../..")
const sourcePath = resolve(repoRoot, "packages/omo-senpi/skills/ultrawork/SKILL.md")
const targetPath = resolve(packageRoot, "src/components/ultrawork/generated-directive.ts")

// The directive is authored senpi-native (skills/ultrawork/SKILL.md) and senpi HAS
// goal/todo/task/team tools, so the source speaks them directly. These tokens name
// harness surfaces senpi does not have; any match means other-edition text leaked in,
// and the build MUST fail loudly — silently stripping blocks is how the old
// codex-derived pipeline shipped mangled sentences.
const forbiddenDirectiveTokens = [
  "multi_agent",
  "spawn_agent",
  "update_plan",
  "wait_agent",
  "fork_context",
  "fork_turns",
  "codex",
]

const forbiddenPatterns = forbiddenDirectiveTokens.map((token) => new RegExp(token, "i"))

function normalizeNewlines(value) {
  return value.replace(/\r\n/g, "\n").replace(/\r/g, "\n")
}

function splitBlocks(value) {
  return normalizeNewlines(value).split(/\n{2,}/)
}

function extractSkillBody(rawSkill) {
  const normalized = normalizeNewlines(rawSkill)
  const frontmatter = normalized.match(/^---\n[\s\S]*?\n---\n+/)
  return frontmatter === null ? normalized : normalized.slice(frontmatter[0].length)
}

export function transformDirective(rawSkill) {
  const body = extractSkillBody(rawSkill)
  const violations = []
  for (const block of splitBlocks(body)) {
    for (const pattern of forbiddenPatterns) {
      if (pattern.test(block)) {
        violations.push(`/${pattern.source}/i: ${block.trim().slice(0, 120)}`)
      }
    }
  }
  if (violations.length > 0) {
    throw new Error(`senpi ultrawork directive source contains forbidden non-senpi tokens:\n  - ${violations.join("\n  - ")}`)
  }

  return `${body.trim()}\n`
}

function renderGeneratedModule(directive) {
  return [
    "export const FORBIDDEN_DIRECTIVE_TOKENS = [",
    ...forbiddenDirectiveTokens.map((token) => `  ${JSON.stringify(token)},`),
    "] as const",
    "",
    `export const SENPI_ULTRAWORK_DIRECTIVE = ${JSON.stringify(directive)} as const`,
    "",
  ].join("\n")
}

function readExpectedModule() {
  return renderGeneratedModule(transformDirective(readFileSync(sourcePath, "utf8")))
}

function main(argv) {
  let expected
  try {
    expected = readExpectedModule()
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error))
    process.exit(1)
  }

  if (argv.includes("--check")) {
    const actual = readFileSync(targetPath, "utf8")
    if (actual !== expected) {
      console.error(`generated directive drifted: ${targetPath}`)
      process.exit(1)
    }
    console.log(`generated directive is current: ${targetPath}`)
    return
  }

  writeFileSync(targetPath, expected)
  console.log(`generated ${targetPath}`)
}

main(process.argv.slice(2))

#!/usr/bin/env bun
// @bun

// packages/omo-senpi/src/install/cli-local.ts
import { existsSync as existsSync2, readFileSync } from "fs";
import { dirname as dirname3, join as join3, resolve as resolve3 } from "path";
import { fileURLToPath as fileURLToPath2 } from "url";

// packages/omo-senpi/src/install/install-senpi.ts
import { execFile } from "node:child_process";
import { createHash } from "node:crypto";
import { constants as constants2, existsSync } from "node:fs";
import { access as access2, readFile as readFile2, stat } from "node:fs/promises";
import { homedir } from "node:os";
import { dirname as dirname2, join as join2, resolve as resolve2 } from "node:path";
import { fileURLToPath } from "node:url";
import { promisify } from "node:util";

// packages/omo-senpi/src/install/senpi-settings.ts
import { constants } from "node:fs";
import { access, copyFile, mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
var OMO_SENPI_PACKAGE_NAME = "@code-yeongyu/omo-senpi";
var LEGACY_BUILTIN_SHADOW_PACKAGES = [
  join("packages", "pi-goal"),
  join("packages", "pi-webfetch")
];
async function readSettings(settingsPath) {
  let raw;
  try {
    raw = await readFile(settingsPath, "utf8");
  } catch (error) {
    if (isErrno(error, "ENOENT"))
      return {};
    throw error;
  }
  const parsed = JSON.parse(raw);
  if (!isRecord(parsed))
    throw new Error(`${settingsPath} must contain a JSON object`);
  return parsed;
}
function readPackages(settings) {
  const packages = settings.packages;
  if (packages === undefined)
    return [];
  if (!Array.isArray(packages) || !packages.every((entry) => typeof entry === "string")) {
    throw new Error("Senpi settings packages must be an array of strings");
  }
  return packages;
}
function dedupePackages(packages) {
  return [...new Set(packages)];
}
function removeLegacyBuiltinShadows(packages, repoRoot, agentDir) {
  const shadowPaths = new Set(LEGACY_BUILTIN_SHADOW_PACKAGES.map((path) => resolve(repoRoot, path)));
  return packages.filter((entry) => !shadowPaths.has(resolve(agentDir, entry)));
}
async function removeSupersededOmoPackages(packages, currentPluginPath, agentDir) {
  const currentPath = resolve(currentPluginPath);
  const entries = await Promise.all(packages.map(async (entry) => {
    const packagePath = resolve(agentDir, entry);
    if (packagePath === currentPath)
      return currentPath;
    return await readPackageName(packagePath) === OMO_SENPI_PACKAGE_NAME ? undefined : entry;
  }));
  return entries.filter((entry) => entry !== undefined);
}
async function writeSettingsAtomically(settingsPath, settings) {
  await mkdir(dirname(settingsPath), { recursive: true });
  const backupPath = await nextBackupPath(settingsPath);
  if (await fileExists(settingsPath)) {
    await copyFile(settingsPath, backupPath);
  } else {
    await writeFile(backupPath, `{}
`, "utf8");
  }
  const tempPath = `${settingsPath}.${process.pid}.${Date.now()}.tmp`;
  await writeFile(tempPath, `${JSON.stringify(settings, null, 2)}
`, "utf8");
  await rename(tempPath, settingsPath);
  return backupPath;
}
async function nextBackupPath(settingsPath) {
  for (let index = 0;index < 1000; index += 1) {
    const suffix = index === 0 ? "" : `-${index}`;
    const candidate = `${settingsPath}.${timestampForBackup()}${suffix}.backup`;
    if (!await fileExists(candidate))
      return candidate;
  }
  throw new Error(`Unable to allocate backup path for ${settingsPath}`);
}
function timestampForBackup() {
  return new Date().toISOString().replace(/[-:.]/g, "");
}
function isRecord(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
async function readPackageName(packagePath) {
  let raw;
  try {
    raw = await readFile(join(packagePath, "package.json"), "utf8");
  } catch (error) {
    if (isErrno(error, "ENOENT") || isErrno(error, "ENOTDIR"))
      return;
    throw error;
  }
  const parsed = JSON.parse(raw);
  return isRecord(parsed) && typeof parsed.name === "string" ? parsed.name : undefined;
}
async function fileExists(path) {
  try {
    await access(path, constants.F_OK);
    return true;
  } catch (error) {
    if (isErrno(error, "ENOENT"))
      return false;
    throw error;
  }
}
function isErrno(error, code) {
  return error instanceof Error && "code" in error && error.code === code;
}

// packages/omo-senpi/src/install/install-senpi.ts
var execFileAsync = promisify(execFile);
var REQUIRED_PLUGIN_ARTIFACTS = [
  join2("extensions", "omo.js"),
  join2("skills", "ast-grep", "SKILL.md"),
  join2("skills", "coding-agent-sessions", "SKILL.md"),
  join2("skills", "debugging", "SKILL.md"),
  join2("skills", "frontend", "SKILL.md"),
  join2("skills", "git-master", "SKILL.md"),
  join2("skills", "init-deep", "SKILL.md"),
  join2("skills", "lsp-setup", "SKILL.md"),
  join2("skills", "programming", "SKILL.md"),
  join2("skills", "refactor", "SKILL.md"),
  join2("skills", "remove-ai-slops", "SKILL.md"),
  join2("skills", "review-work", "SKILL.md"),
  join2("skills", "start-work", "SKILL.md"),
  join2("skills", "ultimate-browsing", "SKILL.md"),
  join2("skills", "ultrawork", "SKILL.md"),
  join2("skills", "ulw-loop", "SKILL.md"),
  join2("skills", "ulw-plan", "SKILL.md"),
  join2("skills", "ulw-research", "SKILL.md"),
  join2("skills", "visual-qa", "SKILL.md"),
  join2("runtime", "ast-grep-mcp", "cli.js"),
  join2("runtime", "agent-toolkit", "cli.js"),
  join2("runtime", "agent-toolkit", "ulw-loop", "cli.js"),
  join2("runtime", "agent-toolkit", "omo-agent-toolkit"),
  join2("runtime", "agent-toolkit", "omo-agent-toolkit.cmd"),
  join2("runtime", "lsp-daemon", "dist", "cli.js"),
  join2("runtime", "lsp-daemon", "dist", "index.js"),
  join2("runtime", "lsp-daemon", "dist", "index.d.ts"),
  join2("runtime", "lsp-daemon", "dist", "daemon-client.js"),
  join2("runtime", "lsp-daemon", "dist", "daemon-client.d.ts"),
  join2("runtime", "lsp-daemon", "dist", "package.json"),
  join2("runtime", "lsp-daemon", "dist", ".omo-runtime-manifest.json"),
  join2("scripts", "install.mjs")
];
async function runSenpiInstaller(options = {}) {
  const context = resolveInstallContext(options);
  await ensurePluginArtifacts(context);
  const settings = await readSettings(context.settingsPath);
  const before = JSON.stringify(settings);
  const packages = dedupePackages(await removeSupersededOmoPackages(removeLegacyBuiltinShadows(dedupePackages(readPackages(settings)), context.repoRoot, context.agentDir), context.pluginPath, context.agentDir));
  if (!packages.includes(context.pluginPath))
    packages.push(context.pluginPath);
  settings.packages = packages;
